def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Detect the solid 3 stripe (tile-sized) and clear it.
    row_runs, col_runs = [], []
    for r in range(h):
        if all(grid[r][c] == 3 for c in range(w)):
            if row_runs and r == row_runs[-1][-1] + 1: row_runs[-1].append(r)
            else: row_runs.append([r])
    for c in range(w):
        if all(grid[r][c] == 3 for r in range(h)):
            if col_runs and c == col_runs[-1][-1] + 1: col_runs[-1].append(c)
            else: col_runs.append([c])
    runs = row_runs or col_runs
    size = len(max(runs, key=len)) if runs else 3
    pitch = size + 1
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3: out[r][c] = 0
    def get_tile(r0,c0):
        if r0 < 0 or c0 < 0 or r0+size > h or c0+size > w: return None
        t=tuple(tuple(grid[r][c] for c in range(c0,c0+size)) for r in range(r0,r0+size))
        return t if any(v==2 for row in t for v in row) else None
    def put_tile(r0,c0,t):
        for i in range(size):
            for j in range(size): out[r0+i][c0+j]=t[i][j]
    # Complete a hidden tile stripe from the occupied neighboring pattern(s).
    for run in row_runs:
        r0=run[0]
        # Adjacent motif rows, skipping the one-cell gutters.
        candidates=[]
        for tr in range(0,h-size+1,pitch):
            if tr+size <= r0 or tr >= run[-1]+1:
                for c0 in range(0,w-size+1,pitch):
                    t=get_tile(tr,c0)
                    if t: candidates.append((tr,c0,t))
        from collections import Counter
        counts=Counter(t for _,_,t in candidates)
        common=counts.most_common(1)[0][0] if counts else None
        for c0 in range(0,w-size+1,pitch):
            possible=[get_tile(tr,c0) for tr in range(0,h-size+1,pitch) if tr+size<=r0 or tr>=run[-1]+1]
            possible=[t for t in possible if t]
            if possible:
                t=common if common in possible else possible[0]
                put_tile(r0,c0,t)
    for run in col_runs:
        c0=run[0]
        for r0 in range(0,h-size+1,pitch):
            possible=[get_tile(r0,tc) for tc in range(0,w-size+1,pitch) if tc+size<=c0 or tc>=run[-1]+1]
            possible=[t for t in possible if t]
            if possible: put_tile(r0,c0,possible[0])
    # Each tile carries a marker at the cell indexed by its tile row and column.
    for r0 in range(0,h-size+1,pitch):
        for c0 in range(0,w-size+1,pitch):
            dr,dc=r0//pitch,c0//pitch
            if dr<size and dc<size and out[r0+dr][c0+dc]==2:
                out[r0+dr][c0+dc]=8
    return out
